data: {"type":"custom_event","foo":"bar"}

// Node 18+ / Bun / Deno — your server.
import OpenAI from 'openai';

app.post('/v1/agent', async (req, res) => {
  const { query, userId } = req.body;
  res.setHeader('Content-Type', 'text/event-stream');
  res.setHeader('Cache-Control', 'no-cache');
  res.flushHeaders();

  // ... look up history by userId, build prompt, call any LLM ...
  const stream = await openai.chat.completions.create({
    model: 'gpt-4o-mini',
    stream: true,
    messages: [...history, { role: 'user', content: query }],
  });

  for await (const chunk of stream) {
    const delta = chunk.choices[0]?.delta?.content;
    if (delta) {
      res.write(`data: ${JSON.stringify({ type: 'assistant_token', delta })}\n\n`);
    }
  }
  res.write('data: [DONE]\n\n');
  res.end();
});

